BEGIN;
SET LOCAL lock_timeout = '5s';
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM pg_constraint WHERE conname='code_symbols_kind_check'
             AND pg_get_constraintdef(oid) LIKE '%doc%') THEN
    RAISE EXCEPTION '254: kind already permits doc -- nothing to do';
  END IF;
END $$;
ALTER TABLE code_symbols DROP CONSTRAINT code_symbols_kind_check;
ALTER TABLE code_symbols ADD CONSTRAINT code_symbols_kind_check
  CHECK (kind = ANY (ARRAY['func','method','struct','interface','alias','type','var','const','doc']));
COMMIT;
-- No new index: idx_code_symbols_body_trgm already covers body, and the content
-- search ORs body with content. Markdown rides layer 1's mechanism.

BEGIN;
-- 1. the doc rows MUST go first: re-adding the old CHECK is validated against
--    existing data, so a single surviving kind='doc' row fails the ALTER.
DELETE FROM code_symbols WHERE kind = 'doc';
-- 2. restore the pre-254 constraint verbatim
ALTER TABLE code_symbols DROP CONSTRAINT code_symbols_kind_check;
ALTER TABLE code_symbols ADD CONSTRAINT code_symbols_kind_check
  CHECK (kind = ANY (ARRAY['func','method','struct','interface','alias','type','var','const']));
-- 3. prove it: no doc rows, and the constraint no longer admits one
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM code_symbols WHERE kind='doc') THEN
    RAISE EXCEPTION 'ROLLBACK 254: doc rows survived the delete';
  END IF;
END $$;
COMMIT;
